import{_ as i,o as t,c as a,ae as n}from"./chunks/framework.vXWZTEWX.js";const h=JSON.parse('{"title":"ADR 013: Frontend Localization and Security Hardening","description":"","frontmatter":{},"headers":[],"relativePath":"adr/013-frontend-localization-security.md","filePath":"adr/013-frontend-localization-security.md"}'),o={name:"adr/013-frontend-localization-security.md"};function r(s,e,l,c,u,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-013-frontend-localization-and-security-hardening" tabindex="-1">ADR 013: Frontend Localization and Security Hardening <a class="header-anchor" href="#adr-013-frontend-localization-and-security-hardening" aria-label="Permalink to &quot;ADR 013: Frontend Localization and Security Hardening&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted Date: 2026-03-04</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The application targets the Spanish public procurement market (&quot;Licitaciones Públicas&quot;), requiring a fully localized interface. Additionally, security best practices (OWASP) dictate preventing User Enumeration attacks, and accessibility standards (WCAG 2.1 AA) require usable forms for all users.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Full Spanish Localization</strong>: All user-facing text (Landing Page, Auth Forms, Dashboard) has been translated to Spanish to align with the target audience. <ul><li>Terms: &quot;Pliegos&quot; (Tenders), &quot;Ofertas&quot; (Proposals), &quot;Cumplimiento&quot; (Compliance).</li></ul></li><li><strong>Security Hardening (Anti-Enumeration)</strong>: <ul><li><strong>Registration</strong>: Generic error message (&quot;No se pudo crear la cuenta&quot;) instead of specific &quot;User already exists&quot;.</li><li><strong>Login</strong>: Generic error message (&quot;Credenciales inválidas&quot;) for all authentication failures.</li></ul></li><li><strong>Accessibility Improvements</strong>: <ul><li><strong>Auto-focus</strong>: Enabled on primary inputs to reduce friction.</li><li><strong>Font Size</strong>: Minimum 16px to prevent iOS zoom.</li><li><strong>Focus Rings</strong>: Enhanced visibility (<code>ring-2</code>, <code>emerald-400</code>) for keyboard navigation.</li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positives</strong>: <ul><li>Improved user experience for Spanish-speaking officials.</li><li>Reduced attack surface (no user enumeration).</li><li>Compliance with accessibility standards.</li></ul></li><li><strong>Negatives</strong>: <ul><li>Debugging user issues might be slightly harder without specific error messages (mitigated by server-side logging).</li></ul></li></ul>',9)])])}const p=i(o,[["render",r]]);export{h as __pageData,p as default};
